     1→import type { IconData } from "@/components/ui/icon-picker";
     2→import type {
     3→  BreadcrumbStackItem,
     4→  VirtualPageIndexNode,
     5→  WorkspaceSection,
     6→  DesktopLocation,
     7→} from "./navigation-meta";
     8→import {
     9→  SETTINGS_SECTION_DESCRIPTORS,
    10→  getWorkspaceSectionDescriptor,
    11→  getWorkspaceSectionRoutePath,
    12→  WORKSPACE_SECTION_DESCRIPTORS,
    13→  getSettingsSectionIcon,
    14→  getSettingsSectionLabel,
