    20→export interface DesktopBreadcrumbSegment {
    21→  id?: string;
    22→  label: string;
    23→  href: string;
    24→  path?: string;
    25→  onClick?: () => void;
    26→  icon?: IconData;
    27→  descriptorId?: string;
    28→  meta?: {
    29→    workspaceId?: string;
    30→    section?: WorkspaceSection;
    31→    routePath?: string;
    32→    pageSlug?: string;
    33→    agentId?: string;
    34→    executorType?: string;
