    99→type WorkspaceSectionDropdownBuilder = (
   100→  input: WorkspaceSectionDropdownInput
   101→) => BreadcrumbDropdownItem[];
   102→
   103→function buildDropdownItems<T>(
   104→  items: T[],
   105→  mapItem: (item: T, index: number) => BreadcrumbDropdownItem | null | undefined
   106→): BreadcrumbDropdownItem[] {
   107→  return items
   108→    .map((item, index) => mapItem(item, index))
   109→    .filter((item): item is BreadcrumbDropdownItem => Boolean(item));
   110→}
   111→
   112→export function stackToDesktopSegments(
   113→  stack: BreadcrumbStackItem[] | undefined
   114→): DesktopBreadcrumbSegment[] {
   115→  if (!stack || stack.length <= 1) {
   116→    return [];
   117→  }
   118→
   119→  return stack.slice(1).map((item) => ({
   120→    id: item.id,
   121→    label: item.label,
   122→    href: item.target?.canonicalUrl ?? "#",
   123→    icon: item.icon,
   124→    descriptorId: item.descriptorId,
   125→    meta: item.meta,
   126→  }));
   127→}
   128→
   129→export function buildFallbackDesktopSegment(input: {
   130→  id: string;
   131→  label: string;
   132→  location: DesktopLocation;
   133→  descriptorId: string;
   134→  icon?: IconData;
   135→  meta?: DesktopBreadcrumbSegment["meta"];
   136→}): DesktopBreadcrumbSegment {
   137→  const item = createBreadcrumbItem({
   138→    id: input.id,
   139→    label: input.label,
   140→    location: input.location,
   141→    descriptorId: input.descriptorId,
   142→    icon: input.icon,
   143→    meta: input.meta,
   144→  });
   145→
   146→  return {
   147→    id: item.id,
   148→    label: item.label,
   149→    href: item.target?.canonicalUrl ?? "#",
   150→    icon: item.icon,
   151→    descriptorId: item.descriptorId,
   152→    meta: item.meta,
   153→  };
   154→}
   155→
   156→export function buildWorkspaceSectionHeaderSegment(
   157→  workspaceId: string,
   158→  section: WorkspaceSection,
   159→  buildLabel?: (titleKey: string, fallbackLabel: string) => string
   160→): DesktopBreadcrumbSegment {
   161→  const descriptor = getWorkspaceSectionDescriptor(section);
   162→  const routePath = descriptor?.routePath ?? section;
   163→
   164→  return {
   165→    id: `workspace:${workspaceId}:${section}`,
   166→    label: descriptor
   167→      ? buildLabel?.(descriptor.titleKey, descriptor.fallbackLabel) ??
   168→        descriptor.fallbackLabel
   169→      : section,
   170→    href: `/workspace/${encodeURIComponent(workspaceId)}/${routePath}`,
   171→    icon: descriptor?.icon,
   172→    descriptorId: `workspace-section:${section}`,
   173→    meta: {
   174→      workspaceId,
   175→      section,
   176→      routePath,
   177→    },
   178→  };
   179→}
   180→
   181→export function resolveHeaderSegments(input: {
   182→  stack?: BreadcrumbStackItem[];
   183→  fallback?: DesktopBreadcrumbSegment[];
   184→  patchLast?: Partial<DesktopBreadcrumbSegment> & {
   185→    meta?: DesktopBreadcrumbSegment["meta"];
   186→  };
   187→}): DesktopBreadcrumbSegment[] {
   188→  const stackSegments = stackToDesktopSegments(input.stack);
   189→  const patchLast = input.patchLast;
   190→
   191→  if (stackSegments.length === 0) {
   192→    return input.fallback ?? [];
   193→  }
   194→
   195→  if (!patchLast) {
   196→    return stackSegments;
   197→  }
   198→
   199→  return stackSegments.map((segment, index, segments) =>
   200→    index === segments.length - 1
   201→      ? {
   202→          ...segment,
   203→          ...patchLast,
   204→          meta: {
   205→            ...segment.meta,
   206→            ...patchLast.meta,
   207→          },
   208→        }
   209→      : segment
   210→  );
   211→}
