   213→export function createWorkspaceRootNode(
   214→  workspaceId: string,
   215→  label = "Workspace"
   216→): VirtualPageIndexNode {
   217→  return {
   218→    id: `workspace:${workspaceId}`,
   219→    descriptorId: "workspace",
   220→    label,
   221→    icon: { type: "lucide", value: "folder-open" },
   222→    order: 0,
   223→    isContainer: true,
   224→  };
   225→}
   226→
   227→export function createStaticWorkspaceIndexNodes(
   228→  workspaceId: string
   229→): VirtualPageIndexNode[] {
   230→  const root = createWorkspaceRootNode(workspaceId);
   231→  const sectionNodes = WORKSPACE_SECTION_DESCRIPTORS.map((section, index) => ({
   232→    id: `${root.id}:${section.section}`,
   233→    descriptorId: section.id,
   234→    label: section.fallbackLabel,
   235→    icon: section.icon,
   236→    parentId: root.id,
   237→    order: index + 1,
   238→    target: {
   239→      key: `workspace:${workspaceId}:${section.section}`,
   240→      canonicalUrl: `/workspace/${encodeURIComponent(workspaceId)}/${section.routePath}`,
   241→      location: {
   242→        kind: "workspace-section" as const,
   243→        workspaceId,
   244→        section: section.section,
   245→      },
   246→    },
   247→  }));
   248→
   249→  return [root, ...sectionNodes];
   250→}
   251→
   252→export function resolveSegmentDescriptorId(
   253→  segment: DesktopBreadcrumbSegment
   254→): string | undefined {
   255→  if (segment.descriptorId) {
   256→    return segment.descriptorId;
   257→  }
   258→
   259→  if (/^\/workspace\/[^/]+$/.test(segment.href)) {
   260→    return "workspace";
   261→  }
   262→
   263→  const sectionMatch = segment.href.match(
   264→    /^\/workspace\/[^/]+\/(chat|kanban|cron|ideas|files|github|chat-monitor)$/
   265→  );
   266→  if (sectionMatch) {
   267→    return `workspace-section:${sectionMatch[1]}`;
   268→  }
   269→
   270→  if (/^\/workspace\/[^/]+\/(agent|agents)$/.test(segment.href)) {
   271→    return "workspace-section:agent";
   272→  }
   273→
   274→  if (/^\/agent\/[^/]+/.test(segment.href)) {
   275→    return "workspace-agent";
   276→  }
   277→
   278→  if (/^\/executor\/[^/]+/.test(segment.href)) {
   279→    return "workspace-executor";
   280→  }
   281→
   282→  return undefined;
   283→}
