   285→export function buildRootDropdownItems({
   286→  workspaces = [],
   287→  currentArea = "home",
   288→  activeWorkspaceId,
   289→  currentSection,
   290→  activeHref,
   291→  buildLabel,
   292→  onSelectWorkspace,
   293→  labelGlobalWorkspace,
   294→}: {
   295→  workspaces?: WorkspaceListItemLike[];
   296→  currentArea?: "home" | "apps" | "section";
   297→  activeWorkspaceId?: string;
   298→  currentSection?: WorkspaceSection;
   299→  activeHref?: string;
   300→  buildLabel?: (titleKey: string, fallbackLabel: string) => string;
   301→  onSelectWorkspace?: (workspaceId: string) => void;
   302→  labelGlobalWorkspace?: string;
   303→}): BreadcrumbDropdownItem[] {
   304→  const sectionRoutePath = currentSection
   305→    ? getWorkspaceSectionRoutePath(currentSection)
   306→    : "";
   307→
   308→  const workspaceItems = buildDropdownItems(workspaces, (workspace) => {
   309→    const workspaceLabel =
   310→      workspace.type === "global"
   311→        ? labelGlobalWorkspace ??
   312→          buildLabel?.("workspace.global", "Global Workspace") ??
   313→          "Global Workspace"
   314→        : workspace.name;
   315→    const href =
   316→      currentArea === "apps"
   317→        ? `/workspace/${encodeURIComponent(workspace.id)}/apps`
   318→        : sectionRoutePath
   319→          ? `/workspace/${encodeURIComponent(workspace.id)}/${sectionRoutePath}`
   320→          : `/workspace/${encodeURIComponent(workspace.id)}`;
   321→
   322→    return {
   323→      id: `workspace:${workspace.id}`,
   324→      label: workspaceLabel,
   325→      href,
   326→      description: workspace.path,
   327→      icon: {
   328→        type: "lucide",
   329→        value: workspace.type === "global" ? "globe" : "folder-open",
   330→      } as IconData,
   331→      isActive: workspace.id === activeWorkspaceId,
   332→      descriptorId: "workspace",
   333→      meta: {
   334→        workspaceId: workspace.id,
   335→        section: currentSection,
   336→        routePath: sectionRoutePath || undefined,
   337→      },
   338→      onSelect: onSelectWorkspace
   339→        ? () => onSelectWorkspace(workspace.id)
   340→        : undefined,
   341→    };
   342→  });
   343→
   344→  const systemItems = buildDropdownItems(
   345→    [
   346→      {
   347→        id: "root:settings",
   348→        label: getSettingsSectionLabel(),
   349→        href: "/settings/general",
   350→        icon: getSettingsSectionIcon(),
   351→        isActive: activeHref?.startsWith("/settings") ?? false,
   352→      },
   353→      {
   354→        id: "root:documents",
   355→        label: buildLabel?.("nav.documents", "Documents") ?? "Documents",
   356→        href: "/documents",
   357→        icon: { type: "lucide", value: "file-text" } as IconData,
   358→        isActive: activeHref === "/documents",
   359→      },
   360→      {
   361→        id: "root:devices",
   362→        label: buildLabel?.("nav.devices", "Devices") ?? "Devices",
   363→        href: "/devices/pair",
   364→        icon: { type: "lucide", value: "smartphone" } as IconData,
   365→        isActive: activeHref === "/devices/pair",
   366→      },
   367→    ],
   368→    (item) => ({
   369→      ...item,
   370→      descriptorId: item.id.replace("root:", ""),
   371→    })
   372→  );
   373→
   374→  return [...workspaceItems, ...systemItems];
   375→}
