   377→function buildWorkspaceSectionMenuDropdownItems({
   378→  workspaceId,
   379→  activeSection,
   380→  buildLabel,
   381→  onSelectSection,
   382→  allowGithub = true,
   383→}: {
   384→  workspaceId: string;
   385→  activeSection?: WorkspaceSection;
   386→  buildLabel?: (titleKey: string, fallbackLabel: string) => string;
   387→  onSelectSection?: (
   388→    section: WorkspaceSection,
   389→    routePath: string,
   390→    href: string
   391→  ) => void;
   392→  allowGithub?: boolean;
   393→}): BreadcrumbDropdownItem[] {
   394→  return buildDropdownItems(
   395→    WORKSPACE_SECTION_DESCRIPTORS.filter((item) =>
   396→      allowGithub ? true : item.section !== "github"
   397→    ),
   398→    (item) => {
   399→      const href = `/workspace/${encodeURIComponent(workspaceId)}/${item.routePath}`;
   400→      return {
   401→        id: `workspace:${workspaceId}:${item.section}`,
   402→        label:
   403→          buildLabel?.(item.titleKey, item.fallbackLabel) ?? item.fallbackLabel,
   404→        href,
   405→        icon: item.icon,
   406→        isActive: item.section === activeSection,
   407→        descriptorId: item.id,
   408→        meta: {
   409→          workspaceId,
   410→          section: item.section,
   411→          routePath: item.routePath,
   412→        },
   413→        onSelect: onSelectSection
   414→          ? () => onSelectSection(item.section, item.routePath, href)
   415→          : undefined,
   416→      };
   417→    }
   418→  );
   419→}
