   504→      },
   505→
   506→      popTo: (tabId, index) => {
   507→        const tab = get().tabs.find((entry) => entry.id === tabId);
   508→        const current = tab ? normalizeTab(tab) : null;
   509→        const currentState = current ? getTabCurrentState(current) : null;
   510→        if (!current || !currentState) return;
   511→
   512→        const nextState = popNavigationState(currentState, index);
   513→        const matchIndex = findHistoryEntryByLocation(
   514→          current.navigationHistory,
   515→          current.historyIndex,
   516→          nextState.location
   517→        );
   518→
   519→        if (matchIndex >= 0) {
   520→          get().jumpToHistory(tabId, matchIndex);
   521→          return;
   522→        }
   523→
   524→        get().insertHistoryBeforeCurrent(tabId, nextState);
   525→      },
   526→
   527→      resetStack: (tabId, next) => {
   528→        get().replaceLocation(tabId, next);
   529→      },
   530→
   531→      jumpToHistory: (tabId, historyIndex) => {
   532→        set((state) => ({
   533→          tabs: state.tabs.map((tab) => {
   534→            if (tab.id !== tabId) return tab;
   535→            const current = normalizeTab(tab);
   536→            return normalizeTab({
   537→              ...current,
   538→              historyIndex,
   539→            });
   540→          }),
   541→        }));
   542→      },
   543→
   544→      goBack: (tabId) => {
   545→        set((state) => ({
   546→          tabs: state.tabs.map((tab) => {
   547→            if (tab.id !== tabId) return tab;
   548→            const current = normalizeTab(tab);
   549→            if (current.historyIndex <= 0) return current;
   550→            return {
   551→              ...current,
   552→              historyIndex: current.historyIndex - 1,
   553→            };
   554→          }),
   555→        }));
   556→      },
   557→
   558→      goForward: (tabId) => {
   559→        set((state) => ({
   560→          tabs: state.tabs.map((tab) => {
   561→            if (tab.id !== tabId) return tab;
   562→            const current = normalizeTab(tab);
   563→            if (current.historyIndex >= current.navigationHistory.length - 1) {
   564→              return current;
   565→            }
   566→            return {
   567→              ...current,
   568→              historyIndex: current.historyIndex + 1,
   569→            };
   570→          }),
   571→        }));
   572→      },
   573→
   574→      canGoBack: (tabId) => {
   575→        const tab = get().tabs.find((item) => item.id === tabId);
   576→        return tab ? normalizeTab(tab).historyIndex > 0 : false;
   577→      },
   578→
   579→      canGoForward: (tabId) => {
   580→        const tab = get().tabs.find((item) => item.id === tabId);
   581→        if (!tab) return false;
   582→        const current = normalizeTab(tab);
   583→        return current.historyIndex < current.navigationHistory.length - 1;
   584→      },
   585→
   586→      getCurrentUrl: (tabId) => {
   587→        const tab = get().tabs.find((item) => item.id === tabId);
   588→        return tab ? getTabUrl(normalizeTab(tab)) : null;
   589→      },
   590→
   591→      getCurrentNavigationState: (tabId) => {
   592→        const tab = get().tabs.find((item) => item.id === tabId);
   593→        return tab ? getTabCurrentState(normalizeTab(tab)) : null;
   594→      },
   595→
   596→      closeAllTabs: () => {
   597→        set((state) => {
   598→          const snapshots = state.tabs
   599→            .map((tab, index) => ({ tab, index }))
   600→            .filter(({ tab }) => !tab.pinned)
   601→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   602→          const tabs = state.tabs.filter((tab) => tab.pinned);
   603→          return {
   604→            tabs,
   605→            activeTabId: tabs[0]?.id ?? null,
   606→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   607→          };
   608→        });
   609→      },
   610→
   611→      duplicateTab: (tabId) => {
   612→        const state = get();
   613→        const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   614→        if (tabIndex === -1) return null;
   615→
   616→        const duplicatedTab = cloneTabWithNewId(state.tabs[tabIndex], {
   617→          pinned: false,
   618→        });
   619→
   620→        set((current) => {
   621→          const tabs = [...current.tabs];
   622→          tabs.splice(tabIndex + 1, 0, duplicatedTab);
   623→          return {
   624→            tabs,
   625→            activeTabId: duplicatedTab.id,
   626→          };
   627→        });
   628→
   629→        return duplicatedTab.id;
   630→      },
   631→
   632→      reopenClosedTab: () => {
   633→        let restoredTabId: string | null = null;
   634→
   635→        set((current) => {
   636→          const [nextSnapshot, ...restSnapshots] = current.recentlyClosedTabs;
   637→          if (!nextSnapshot) return current;
   638→
   639→          const restored = restoreClosedTabIntoTabs(current.tabs, nextSnapshot);
   640→          restoredTabId = restored.restoredTab.id;
   641→
   642→          return {
   643→            tabs: restored.tabs,
   644→            activeTabId: restored.restoredTab.id,
   645→            recentlyClosedTabs: restSnapshots,
   646→          };
   647→        });
   648→
   649→        return restoredTabId;
   650→      },
   651→
   652→      restoreTab: (tab) => {
   653→        const restoredTab = cloneTabWithNewId(tab);
   654→        set((state) => ({
   655→          tabs: [...state.tabs, restoredTab],
   656→          activeTabId: restoredTab.id,
   657→        }));
   658→      },
   659→    }),
   660→    {
   661→      name: TAB_STORE_STORAGE_KEY,
   662→      partialize: (state) => ({
   663→        tabs: state.tabs,
   664→        activeTabId: state.activeTabId,
   665→        recentlyClosedTabs: state.recentlyClosedTabs,
   666→      }),
   667→      merge: (persisted, current) => {
   668→        return {
   669→          ...current,
   670→          ...mergePersistedTabState(
   671→            persisted as Partial<TabState> | undefined,
   672→            current
   673→          ),
   674→        };
   675→      },
   676→    }
   677→  )
   678→);
   679→
   680→export const selectActiveTab = (state: TabState) =>
   681→  state.tabs.find((tab) => tab.id === state.activeTabId) ?? null;
   682→
   683→export const selectPinnedTabs = (state: TabState) =>
   684→  state.tabs.filter((tab) => tab.pinned);
   685→
   686→export const selectUnpinnedTabs = (state: TabState) =>
   687→  state.tabs.filter((tab) => !tab.pinned);
   688→

