     1→import {
     2→  type DesktopLocation,
     3→  locationToUrl,
     4→  buildViewTarget,
     5→  type BreadcrumbStackItem,
     6→  type PushPageOptions,
     7→  type TabNavigationState,
     8→} from "./navigation-meta";
     9→import { popTo as popBreadcrumbStack, pushStackItem, replaceStackTop } from "./breadcrumb-stack";
    10→
    11→function ensureItemTarget(
    12→  item: BreadcrumbStackItem,
    13→  location: DesktopLocation
    14→): BreadcrumbStackItem {
    15→  return {
    16→    ...item,
    17→    target:
    18→      item.target ??
    19→      buildViewTarget(location, locationToUrl(location)),
    20→  };
    21→}
    22→
    23→export function createTabNavigationState(
    24→  location: DesktopLocation,
    25→  breadcrumbStack: BreadcrumbStackItem[],
    26→  patch?: Partial<TabNavigationState>
    27→): TabNavigationState {
    28→  return {
    29→    location,
    30→    breadcrumbStack,
    31→    activeNodeId: patch?.activeNodeId,
    32→    activeIndexPath: patch?.activeIndexPath,
    33→  };
    34→}
    35→
    36→export function replaceLocation(
    37→  state: TabNavigationState,
    38→  location: DesktopLocation,
    39→  patch?: Partial<TabNavigationState>
    40→): TabNavigationState {
    41→  return {
    42→    ...state,
    43→    ...patch,
    44→    location,
    45→    breadcrumbStack: patch?.breadcrumbStack ?? state.breadcrumbStack,
    46→  };
    47→}
    48→
    49→export function pushPage(
    50→  state: TabNavigationState,
    51→  item: BreadcrumbStackItem,
    52→  location: DesktopLocation,
    53→  options?: PushPageOptions
    54→): TabNavigationState {
    55→  const nextItem = ensureItemTarget(item, location);
    56→  const nextStack =
    57→    options?.mode === "replace"
    58→      ? replaceStackTop(state.breadcrumbStack, nextItem)
    59→      : pushStackItem(state.breadcrumbStack, nextItem);
    60→
    61→  return {
    62→    ...state,
    63→    location,
    64→    breadcrumbStack: nextStack,
    65→  };
    66→}
    67→
    68→export function popTo(
    69→  state: TabNavigationState,
    70→  index: number
    71→): TabNavigationState {
    72→  const nextStack = popBreadcrumbStack(state.breadcrumbStack, index);
    73→  const nextTop = nextStack[nextStack.length - 1];
    74→
    75→  return {
    76→    ...state,
    77→    location: nextTop?.target?.location ?? state.location,
    78→    breadcrumbStack: nextStack,
    79→  };
    80→}
    81→
    82→export function resetStack(next: TabNavigationState): TabNavigationState {
    83→  return next;
    84→}
