   415→function buildDetailQuery(
   416→  workspacePath: string | undefined,
   417→  extraParams?: Record<string, string | undefined>
   418→): string {
   419→  const params = new URLSearchParams();
   420→  if (workspacePath) params.set("workspace_path", workspacePath);
   421→  if (extraParams) {
   422→    Object.entries(extraParams).forEach(([key, value]) => {
   423→      if (value) params.set(key, value);
   424→    });
   425→  }
   426→  const query = params.toString();
   427→  return query ? `?${query}` : "";
   428→}
