   101→  if (!normalized) return null;
   102→  return {
   103→    id: `page:${normalized}:${order}`,
   104→    kind: "page-mention",
   105→    label: label?.trim() || normalized.split("/").filter(Boolean).slice(-1)[0] || normalized,
   106→    order,
   107→    pageSlug: normalized,
   108→    nav,
   109→  };
   110→}
   111→
   112→function buildExternalItem(
   113→  url: string,
   114→  order: number,
   115→  kind: "external-link" | "embed",
   116→  label?: string,
   117→  blockId?: string,
   118→  nav?: YooptaNavigationMeta,
   119→): ExtractedNavigationItem | null {
   120→  if (!RAW_URL_RE.test(url)) return null;
   121→  return {
   122→    id: `${kind}:${url}:${order}`,
   123→    kind,
   124→    label: getExternalLabel(label, url),
   125→    order,
   126→    url,
   127→    blockId,
   128→    nav,
   129→  };
   130→}
   131→
   132→export function extractPageNavigation(
   133→  pageSlug: string,
   134→  content: string,
   135→): PageNavigationExtract {
   136→  const items: ExtractedNavigationItem[] = [];
   137→  const body = content ?? "";
   138→  let order = 0;
   139→
   140→  for (const match of body.matchAll(HTML_COMMENT_NAV_RE)) {
   141→    const nav = parseMeta(match[1]);
   142→    if (!nav) continue;
   143→    const offset = match.index ?? 0;
   144→    const nearby = body.slice(offset + match[0].length, offset + match[0].length + 240);
   145→    const linkMatch = MARKDOWN_LINK_RE.exec(nearby);
   146→    MARKDOWN_LINK_RE.lastIndex = 0;
   147→    if (!linkMatch) continue;
   148→    const [, label, target] = linkMatch;
   149→    const item = RAW_URL_RE.test(target)
   150→      ? buildExternalItem(target, order++, "external-link", label, undefined, nav)
   151→      : buildMentionItem(target, order++, label, nav);
   152→    if (item) pushUnique(items, item);
   153→  }
   154→
   155→  for (const match of body.matchAll(MARKDOWN_LINK_RE)) {
   156→    const label = match[1];
   157→    const target = match[2];
   158→    const item = RAW_URL_RE.test(target)
   159→      ? buildExternalItem(target, order++, "external-link", label)
   160→      : buildMentionItem(target, order++, label);
   161→    if (item) pushUnique(items, item);
   162→  }
   163→
   164→  for (const match of body.matchAll(MARKDOWN_AUTOLINK_RE)) {
   165→    const item = buildExternalItem(match[0], order++, "external-link");
   166→    if (item) pushUnique(items, item);
   167→  }
   168→
   169→  return {
   170→    pageSlug,
   171→    items: items.sort((left, right) => left.order - right.order),
   172→  };
   173→}
   174→
   175→export function collectPageNavigationFromDom(root: ParentNode, pageSlug: string): PageNavigationExtract {
   176→  const items: ExtractedNavigationItem[] = [];
   177→  let order = 0;
   178→
   179→  const mentions = Array.from(root.querySelectorAll<HTMLElement>("[data-mention-type='page'][data-mention-id]"));
   180→  for (const node of mentions) {
   181→    const id = node.dataset.mentionId;
   182→    const item = id ? buildMentionItem(id, order++, node.textContent ?? undefined) : null;
   183→    if (item) pushUnique(items, item);
   184→  }
   185→
   186→  const links = Array.from(root.querySelectorAll<HTMLAnchorElement>("a[href]"));
   187→  for (const link of links) {
   188→    const href = link.getAttribute("href");
   189→    if (!href) continue;
   190→    const item = RAW_URL_RE.test(href)
   191→      ? buildExternalItem(href, order++, "external-link", link.textContent ?? undefined)
   192→      : buildMentionItem(href, order++, link.textContent ?? undefined);
   193→    if (item) pushUnique(items, item);
   194→  }
   195→
   196→  const embeds = Array.from(root.querySelectorAll<HTMLIFrameElement>("iframe[src]"));
   197→  for (const embed of embeds) {
   198→    const src = embed.getAttribute("src");
   199→    if (!src) continue;
   200→    const item = buildExternalItem(src, order++, "embed", embed.title || undefined);
   201→    if (item) pushUnique(items, item);
   202→  }
   203→
   204→  return {
   205→    pageSlug,
   206→    items: items.sort((left, right) => left.order - right.order),
   207→  };
   208→}
